DEEP=[
D('___ what to say, he remained silent.','Not knowing',{'Knowing not':'Olumsuz katılım cümleciğinde not, -ing\'den ÖNCE gelir: Not knowing. "Knowing not" eski/edebî bir kullanımdır, testte yanlış sayılır.','Not knew':'Katılım cümleciği -ing ister; çekimli fiil (knew) katılım oluşturmaz: Not knowing.'}),
D('After ___ the film, we went for dinner.','watching',{'watched':'after bağlaç olarak da edat olarak da kullanılır; bu cümlede özne tekrar edilmediği için -ing gerekir: After watching. (after + V2 olmaz.)'}),
D('___ by the noise, the baby started crying.','Frightened',{'Having frightening':'having + V3 gerekir (having frightened). Ama bu cümlede bebek korkutulan taraftır, bu yüzden edilgen V3 yeterlidir: Frightened by the noise.'}),
D('___ hungry, I made a sandwich.','Feeling',{'Felt':'V3 edilgen anlam verir; burada özne (I) açlığı hisseden taraftır, bu yüzden etken -ing gerekir: Feeling hungry.','Having feel':'having + V3 gerekir (having felt), ayrıca önce/sonra ayrımı burada yok; Feeling yeterlidir.'}),
D('___ lived in Japan for years, she knows the culture well.','Having',{'Had':'Had lived çekimli tam bir fiildir; katılım cümleciği için having + V3 gerekir.','Being':'Being lived diye bir yapı yoktur; "önce yaşamış" anlamı having lived ile verilir.'}),
D('Students ___ to join the trip must pay by Friday.','wishing',{'wished':'V3 edilgen anlam verir ("istenmiş" gibi); burada öğrenciler isteyen taraftır, etken -ing gerekir: students wishing.','wish':'Çekimli fiil yüklem olurdu ve cümlede iki yüklem kalırdı; who wish yerine wishing kullanılır.'}),
D('"After I had read the letter, I tore it up." Aynı anlam hangisi?','Having read the letter, I tore it up.',{'Having reading the letter, I tore it up.':'having + V3 gerekir: having read. "having reading" yapısı yoktur.'}),
D('"Because the book was written for children, it is easy." Aynı anlam hangisi?','Written for children, the book is easy.',{'Writing for children, the book is easy.':'-ing etken anlam verir: kitap yazıyor olurdu. Kitap yazılan nesnedir, V3 gerekir.','Having writing for children, the book is easy.':'having + V3 gerekir (having written); ayrıca zaman farkı olmadığı için V3 yeterlidir.'}),
D('"As I didn\'t want to be late, I took a taxi." Aynı anlam hangisi?','Not wanting to be late, I took a taxi.',{'Wanting not be late, I took a taxi.':'not, -ing\'den önce gelir ve be fiilinin önünde to gerekir: Not wanting to be late.','Not wanted to be late, I took a taxi.':'Katılım cümleciğinde V3 yerine -ing gerekir; not wanted çekimli fiil gibi durur.'}),
D('Hangi cümle doğru?','Seen from the hill, the village looks beautiful.',{'Having seeing from the hill, the village looks beautiful.':'having + V3 gerekir; ayrıca köy görülen taraftır, edilgen V3 (seen) kullanılır.','Seeing from the hill, the village looks beautiful.':'-ing etken: köy bakıyor gibi olurdu. Köy görülendir, edilgen: Seen.'}),
D('Hangi cümle doğru?','Anyone caught cheating will be disqualified.',{'Anyone catching cheating will be disqualified.':'catching etken anlam verir; birini yakalayan değil, yakalanan kişi kastedilir (who is caught = caught).'}),
D('Hangi cümle YANLIŞ (özneler uyuşmuyor)?','Running for the bus, my phone fell out of my pocket.',{'Running for the bus, I dropped my phone.':'Doğru: katılım cümleciğinin öznesi (I) ile ana cümlenin öznesi aynı.'}),
D('Hangi cümle doğru?','Arriving at the station, we found that the train had left.',{'Arrived at the station, we found that the train had left.':'V3 edilgen anlam verir; biz istasyona varan taraftır, etken -ing gerekir.'}),
D('Hangi cümle doğru?','Having been told the news, she called her parents.',{'Being told the news before, she called her parents.':'being, "önce" olduğunu belirtmez ve before ile birlikte yapı hatalı olur; önce olan edilgen eylem için having been + V3 kullanılır.'}),
]
